import React, { useState, useRef } from "react";
import {
  AppBar,
  Toolbar,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
  Box,
  useMediaQuery,
  useTheme,
  Tabs,
  Tab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  Rating,
  TextField,
  Button,
  Avatar,
  Chip,
  CircularProgress,
  Snackbar,
  Alert,
} from "@mui/material";
import { GiHamburgerMenu } from "react-icons/gi";
import { FaTableTennis, FaCloudUploadAlt } from "react-icons/fa";
import { Close } from "@mui/icons-material";
import CustomButton from "../Components/CustomButton";
import { GoogleLogin } from "@react-oauth/google";
import { jwtDecode } from "jwt-decode";

const NavBar = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [currentTab, setCurrentTab] = useState(0);
  const [reviewDialogOpen, setReviewDialogOpen] = useState(false);
  const [authDialogOpen, setAuthDialogOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });
  
  const [reviewData, setReviewData] = useState({
    name: "",
    rating: 0,
    comment: "",
    photo: null,
    photoPreview: null,
  });
  
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const menuItems = ["Home", "About", "Testimonials", "Gallery and Awards"];

  // Google Apps Script Web App URL - Replace with your deployed web app URL
  const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxPNRmGmwW3UbPy55gIh4lEF2wSBFha2QzeoZP6sUsZ9jstktK0wAytJxDDgkgBjV7Q/exec";

  const handleDrawerToggle = () => {
    setDrawerOpen(!drawerOpen);
  };

  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
    console.log("Navigating to:", menuItems[newValue]);
  };

  const handleMobileMenuItemClick = (index) => {
    setCurrentTab(index);
    setDrawerOpen(false);
    console.log("Navigating to:", menuItems[index]);
  };

  // Handle Add Review Button Click
  const handleAddReviewClick = () => {
    if (user) {
      setReviewDialogOpen(true);
    } else {
      setAuthDialogOpen(true);
    }
  };

  // Google Auth Success Handler
  const handleGoogleSuccess = (credentialResponse) => {
    try {
      const decoded = jwtDecode(credentialResponse.credential);
      setUser(decoded);
      setReviewData((prev) => ({
        ...prev,
        name: decoded.name || "",
      }));
      console.log("Google Auth Success:", decoded);

      setAuthDialogOpen(false);
      setReviewDialogOpen(true);
    } catch (error) {
      console.error("Error decoding token:", error);
      showSnackbar("Authentication failed. Please try again.", "error");
    }
  };

  // Google Auth Error Handler
  const handleGoogleError = () => {
    console.log("Google Auth Failed");
    showSnackbar("Google authentication failed. Please try again.", "error");
  };

  // Handle Auth Dialog Close
  const handleAuthDialogClose = () => {
    setAuthDialogOpen(false);
  };

  // Handle Review Dialog Close
  const handleReviewDialogClose = () => {
    setReviewDialogOpen(false);
    setReviewData((prev) => ({
      ...prev,
      photo: null,
      photoPreview: null,
      rating: 0,
      comment: "",
      name: user ? user.name || "" : "",
    }));
  };

  // Handle Photo Upload
  const handlePhotoUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      if (!file.type.startsWith("image/")) {
        showSnackbar("Please upload an image file", "error");
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        showSnackbar("Please upload an image smaller than 5MB", "error");
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        setReviewData((prev) => ({
          ...prev,
          photo: file,
          photoPreview: e.target.result,
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  // Remove uploaded photo
  const handleRemovePhoto = () => {
    setReviewData((prev) => ({
      ...prev,
      photo: null,
      photoPreview: null,
    }));
  };

  // Show snackbar notification
  const showSnackbar = (message, severity = "success") => {
    setSnackbar({
      open: true,
      message,
      severity,
    });
  };

  // Handle Snackbar Close
  const handleSnackbarClose = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  // Convert file to base64 for Google Apps Script
  const fileToBase64 = (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result.split(',')[1]); // Remove data URL prefix
      reader.onerror = error => reject(error);
    });
  };

  // Handle Review Submission to Google Apps Script
const handleReviewSubmit = async () => {
  if (reviewData.rating === 0) {
    showSnackbar("Please provide a rating", "error");
    return;
  }
  if (!reviewData.name.trim()) {
    showSnackbar("Please enter your name", "error");
    return;
  }

  setLoading(true);

  try {
    const reviewPayload = {
      name: reviewData.name,
      rating: reviewData.rating,
      comment: reviewData.comment,
      email: user?.email || "Unknown",
      timestamp: new Date().toISOString(),
    };

    // If photo is uploaded, convert to base64
    if (reviewData.photo) {
      reviewPayload.photo = await fileToBase64(reviewData.photo);
      reviewPayload.photoName = reviewData.photo.name;
      reviewPayload.photoType = reviewData.photo.type;
    }

    console.log("Submitting review:", reviewPayload);

    // Use a proxy or direct POST with CORS handling
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: "POST",
      mode: 'no-cors', // This might help but limits response handling
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(reviewPayload),
    });

    // Since we're using no-cors, we can't read the response
    // Assume success if no error thrown
    showSnackbar("Thank you for your review! It has been submitted successfully.");
    handleReviewDialogClose();
    
  } catch (error) {
    console.error("Error submitting review:", error);
    showSnackbar("Failed to submit review. Please try again.", "error");
  } finally {
    setLoading(false);
  }
};

  const handleInputChange = (field, value) => {
    setReviewData((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const drawerContent = (
    <Box
      sx={{
        width: 280,
        height: "100%",
        background:
          "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        backdropFilter: "blur(10px)",
        color: "white",
        padding: 2,
      }}
    >
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <FaTableTennis className="text-orange-500 text-2xl" />
          <span className="font-in font-bold text-white">BT's TT Academy</span>
        </Box>
        <IconButton onClick={handleDrawerToggle} sx={{ color: "white" }}>
          <Close />
        </IconButton>
      </Box>

      <List>
        {menuItems.map((item, index) => (
          <ListItem
            key={item}
            component="button"
            onClick={() => handleMobileMenuItemClick(index)}
            sx={{
              border:
                currentTab === index
                  ? "1px solid #FF9800"
                  : "1px solid rgba(255,255,255,0.1)",
              borderRadius: "8px",
              marginBottom: 1,
              background:
                currentTab === index
                  ? "rgba(255,165,0,0.2)"
                  : "rgba(255,255,255,0.05)",
              backdropFilter: "blur(10px)",
              transition: "all 0.3s ease",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
                borderColor: "rgba(255,165,0,0.5)",
              },
            }}
          >
            <ListItemText
              primary={item}
              sx={{
                color: currentTab === index ? "#FF9800" : "white",
                "& .MuiListItemText-primary": {
                  fontFamily: "'AlanSans', sans-serif",
                  fontWeight: currentTab === index ? 600 : 500,
                },
              }}
            />
          </ListItem>
        ))}
      </List>

      <Box sx={{ padding: 2 }}>
        <CustomButton
          rating
          size="small"
          onClick={handleAddReviewClick}
          fullWidth
          text="Add Review"
        />
      </Box>
    </Box>
  );

  return (
    <>
      <div
        position="static"
        sx={{
          background: "transparent",
          boxShadow: "none",
          backdropFilter: "blur(10px)",
          background: "rgba(0,0,0,0.1)",
        }}
      >
        <Toolbar sx={{ justifyContent: "space-between", padding: "8px 0" }}>
          {/* Logo */}
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <FaTableTennis className="text-white text-3xl" />
          </Box>

          {/* Desktop Menu with Tabs */}
          <Box
            sx={{
              display: { xs: "none", md: "flex" },
              alignItems: "center",
              gap: 2,
            }}
          >
            <Box
              sx={{
                background: "rgba(0,0,0,0.1)",
                backdropFilter: "blur(10px)",
                borderRadius: "25px",
                border: "1px solid rgba(255,255,255,0.1)",
                padding: "4px",
              }}
            >
              <Tabs
                value={currentTab}
                onChange={handleTabChange}
                sx={{
                  minHeight: "40px",
                  "& .MuiTabs-indicator": {
                    backgroundColor: "#f97316",
                    height: "100%",
                    borderRadius: "20px",
                    boxShadow: "0 2px 8px rgba(255,152,0,0.3)",
                  },
                  "& .MuiTab-root": {
                    color: "rgba(255,255,255,0.7)",
                    fontFamily: "'AlanSans', sans-serif",
                    fontWeight: 500,
                    fontSize: "14px",
                    textTransform: "none",
                    minHeight: "32px",
                    margin: "0 2px",
                    minWidth: "auto",
                    zIndex: 1,
                    transition: "all 0.3s ease",
                    "&.Mui-selected": {
                      color: "white",
                      fontWeight: 600,
                    },
                    "&:hover": {
                      color: "#E2DBD1",
                    },
                  },
                }}
              >
                {menuItems.map((item) => (
                  <Tab key={item} label={item} />
                ))}
              </Tabs>
            </Box>

            {/* Desktop: Custom Add Review Button */}
            <CustomButton
              rating
              size="small"
              text="Add Review"
              onClick={handleAddReviewClick}
            />
          </Box>

          {/* Mobile Menu Button */}
          <IconButton
            sx={{
              display: { xs: "flex", md: "none" },
              color: "white",
              background: "rgba(0,0,0,0.1)",
              backdropFilter: "blur(10px)",
              border: "1px solid rgba(255,255,255,0.1)",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
              },
            }}
            onClick={handleDrawerToggle}
          >
            <GiHamburgerMenu />
          </IconButton>
        </Toolbar>
      </div>

      {/* Mobile Drawer */}
      <Drawer
        variant="temporary"
        anchor="right"
        open={drawerOpen}
        onClose={handleDrawerToggle}
        ModalProps={{
          keepMounted: true,
        }}
        sx={{
          display: { xs: "block", md: "none" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: 280,
            border: "none",
            background: "transparent",
          },
        }}
      >
        {drawerContent}
      </Drawer>

      {/* Authentication Dialog */}
      <Dialog
        open={authDialogOpen}
        onClose={handleAuthDialogClose}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
            textAlign: "center",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography
            variant="h6"
            sx={{ fontFamily: "'AlanSans', sans-serif" }}
          >
            Sign In to Continue
          </Typography>
        </DialogTitle>

        <DialogContent sx={{ padding: 3 }}>
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
            }}
          >
            <FaTableTennis className="text-orange-500 text-4xl" />
            <Typography
              variant="h6"
              sx={{ fontFamily: "'AlanSans', sans-serif" }}
            >
              BT's TT Academy
            </Typography>
            <Typography
              variant="body2"
              sx={{ color: "rgba(255,255,255,0.7)", mb: 2 }}
            >
              Sign in with Google to add your review and share your experience
              with our academy.
            </Typography>

            {/* Custom Google Login Button */}
            <Box sx={{ width: "100%", maxWidth: "200px" }}>
              <GoogleLogin
                onSuccess={handleGoogleSuccess}
                onError={handleGoogleError}
                size="large"
                width="100%"
                shape="circle"
              />
            </Box>
          </Box>
        </DialogContent>

        <DialogActions
          sx={{
            padding: 2,
            justifyContent: "center",
            borderTop: "1px solid rgba(255,255,255,0.1)",
          }}
        >
          <Button
            onClick={handleAuthDialogClose}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
        </DialogActions>
      </Dialog>

      {/* Add Review Dialog */}
      <Dialog
        open={reviewDialogOpen}
        onClose={handleReviewDialogClose}
        maxWidth="sm"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography
            variant="h6"
            sx={{ fontFamily: "'AlanSans', sans-serif" }}
          >
            Add Your Review
          </Typography>
          {user && (
            <Typography
              variant="body2"
              sx={{ color: "rgba(255,255,255,0.7)", mt: 0.5 }}
            >
              Signed in as: {user.name || user.email}
            </Typography>
          )}
        </DialogTitle>

        <DialogContent sx={{ padding: 3 }}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            {/* Name Field */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Name *
              </Typography>
              <TextField
                fullWidth
                value={reviewData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                placeholder="Enter your name"
                variant="outlined"
                disabled={!!user}
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: user
                        ? "rgba(255,255,255,0.2)"
                        : "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                    "& .MuiInputBase-input.Mui-disabled": {
                      WebkitTextFillColor: "rgba(255,255,255,0.7)",
                    },
                  },
                }}
              />
              {user && (
                <Typography
                  variant="caption"
                  sx={{
                    color: "rgba(255,255,255,0.5)",
                    mt: 1,
                    display: "block",
                  }}
                >
                  Name is taken from your Google profile
                </Typography>
              )}
            </Box>

            {/* Photo Upload Field */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Photo (Optional)
              </Typography>

              {reviewData.photoPreview ? (
                <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                  <Avatar
                    src={reviewData.photoPreview}
                    sx={{ width: 80, height: 80, border: "2px solid #FF9800" }}
                  />
                  <Box>
                    <Chip
                      label={reviewData.photo.name}
                      variant="outlined"
                      sx={{
                        color: "white",
                        borderColor: "rgba(255,255,255,0.3)",
                      }}
                    />
                    <Button
                      onClick={handleRemovePhoto}
                      sx={{
                        color: "#FF9800",
                        ml: 1,
                        "&:hover": { background: "rgba(255,152,0,0.1)" },
                      }}
                    >
                      Remove
                    </Button>
                  </Box>
                </Box>
              ) : (
                <Box
                  sx={{
                    border: "2px dashed rgba(255,255,255,0.3)",
                    borderRadius: "8px",
                    padding: 3,
                    textAlign: "center",
                    cursor: "pointer",
                    transition: "all 0.3s ease",
                    "&:hover": {
                      borderColor: "#FF9800",
                      background: "rgba(255,152,0,0.05)",
                    },
                  }}
                  onClick={() =>
                    document.getElementById("photo-upload").click()
                  }
                >
                  <input
                    id="photo-upload"
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoUpload}
                    style={{ display: "none" }}
                  />
                  <FaCloudUploadAlt
                    style={{
                      fontSize: "2rem",
                      color: "#FF9800",
                      marginBottom: 1,
                    }}
                  />
                  <Typography
                    variant="body2"
                    sx={{ color: "rgba(255,255,255,0.7)" }}
                  >
                    Click to upload a photo
                  </Typography>
                  <Typography
                    variant="caption"
                    sx={{ color: "rgba(255,255,255,0.5)" }}
                  >
                    PNG, JPG, JPEG (Max 5MB)
                  </Typography>
                </Box>
              )}
            </Box>

            {/* Rating */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Rating *
              </Typography>
              <Rating
                value={reviewData.rating}
                onChange={(e, newValue) =>
                  handleInputChange("rating", newValue)
                }
                size="large"
                sx={{
                  color: "#FF9800",
                  "& .MuiRating-iconFilled": {
                    color: "#FF9800",
                  },
                }}
              />
            </Box>

            {/* Comment */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Review
              </Typography>
              <TextField
                multiline
                rows={4}
                fullWidth
                value={reviewData.comment}
                onChange={(e) => handleInputChange("comment", e.target.value)}
                placeholder="Share your experience with BT's TT Academy..."
                variant="outlined"
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                  },
                }}
              />
            </Box>
          </Box>
        </DialogContent>

        <DialogActions
          sx={{ padding: 3, borderTop: "1px solid rgba(255,255,255,0.1)" }}
        >
          <Button
            onClick={handleReviewDialogClose}
            disabled={loading}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover:not(:disabled)": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleReviewSubmit}
            variant="contained"
            disabled={!reviewData.name.trim() || reviewData.rating === 0 || loading}
            sx={{
              background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
              "&:hover:not(:disabled)": {
                background: "linear-gradient(45deg, #E65100 30%, #BF360C 90%)",
              },
              "&:disabled": {
                background: "rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.3)",
              },
              minWidth: "120px",
            }}
          >
            {loading ? <CircularProgress size={24} /> : "Submit Review"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleSnackbarClose} 
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </>
  );
};

export default NavBar;
